import{z as p,x as A,o,c as m,q as r,j as n,D as t,d as e,s as E,S as i,b as s}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"safetensors","description":"","frontmatter":{"title":"safetensors","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/safetensors-format.md","filePath":"llm/safetensors-format.md","lastUpdated":1791413859000}'),d={name:"llm/safetensors-format.md"};function B(c,a,f,h,u,D){const l=A("Mermaid");return o(),m("div",null,[a[2]||(a[2]=r('<h1 id="safetensors" tabindex="-1">safetensors <a class="header-anchor" href="#safetensors" aria-label="Permalink to &quot;safetensors&quot;">​</a></h1><div class="epigraph"><p>张量文件应当是可以 mmap 的字节布局加一份 JSON 头，而不是一棵会执行代码的 pickle 树。</p><footer>—— Hugging Face safetensors 规范与安全公告；对照 Python pickle 的任意代码执行面</footer></div><p><a href="/llm/weight-loading-streaming">上一课</a>把加载当成带宽与驻留。格式决定 <em>能不能安全地 mmap、能不能零拷贝、头部是否可读</em>。PyTorch <code>.pt</code> 默认 pickle，恶意文件可在 <code>load</code> 时执行代码。safetensors 用固定头 + 偏移表 + 原始张量字节，加载路径无执行。本课写格式契约与对启动的影响；它不是量化算法，也可以装 FP16 或量化后的块。GGUF 是另一生态的容器，见 <a href="/llm/gguf">GGUF</a>。本单元「引擎里的细节」到 safetensors 收束，下一单元离开 CUDA 服务栈。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>检查点分发是供应链：来自 Hub 的文件被服务进程以高权限打开。pickle 的攻击面不可接受。另一些格式（原始 bin）缺形状与 dtype 元数据，加载慢且易错。缺口是：一份按偏移 mmap 的张量字典，dtype/shape 在头里，校验和可选。加载器按名切片映射到设备，不必把整个文件读进主机 RAM 再 <code>cudaMemcpy</code>——大模型上主机体峰值本身会 OOM。</p><p>多框架：同一文件应对 PyTorch、NumPy、JAX 可读。这要求头是 JSON、体是小端原始数组，而不是 Python 对象图。</p><p><span class="marginnote">safetensors 不管量化语义。文件里可以是 <code>int8</code> 加 scale 张量，语义由模型代码解释。不要说「转成 safetensors 就 4-bit 了」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>文件：8 字节头长、JSON 头（张量名 → dtype, shape, 偏移）、然后数据区对齐。加载：mmap，按张量创建指向文件的视图，再异步拷到 GPU 或直接给 CPU 核。与流式加载配合：按层名顺序拷贝。校验：可选哈希在发布侧做，热路径可跳过或抽检。</p><p>和 GGUF 比：safetensors 不内置分词器与架构超参；那些仍在 <code>config.json</code>。服务启动要读两份。GGUF 把元数据打进同一文件，本地单文件分发更省事。GPU 训练/推理生态以 safetensors + config 为默认。</p>',10)),(o(),n(i,null,{default:t(()=>[E(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PKL%5B%22pickle%20.pt%22%5D%20--%3E%20RCE%5B%22load%20%E6%97%B6%E5%8F%AF%E6%89%A7%E8%A1%8C%E4%BB%A3%E7%A0%81%22%5D%0A%20%20ST%5B%22safetensors%22%5D%20--%3E%20MM%5B%22mmap%20%E5%81%8F%E7%A7%BB%E8%A1%A8%22%5D%0A%20%20MM%20--%3E%20DEV%5B%22%E6%8C%89%E5%BC%A0%E9%87%8F%E6%8B%B7%E5%88%B0%E8%AE%BE%E5%A4%87%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[e("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,[e("无执行 + mmap 使加载器成为纯字节搬运，便于与"),s("a",{href:"/llm/weight-loading-streaming"},"自定义加载流水"),e("重叠。JSON 头解析是一次性 CPU 微秒～毫秒，相对百 GB 搬运可忽略。对齐保证直接转 "),s("code",null,"bfloat16"),e(" 视图合法。跨进程共享只读 mmap 可减冷启动主机内存（fork 前打开），GPU 仍要各自一份设备副本。")],-1)),(o(),n(i,null,{default:t(()=>[E(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20H8%5B%22%E5%89%8D%208%20%E5%AD%97%E8%8A%82%3A%20%E5%A4%B4%E9%95%BF%E5%BA%A6%20N%22%5D%20--%3E%20J%5B%22JSON%20%E5%A4%B4%3A%20%E5%BC%A0%E9%87%8F%E5%90%8D%20%E6%98%A0%E5%B0%84%20dtype%2C%20shape%2C%20%E5%81%8F%E7%A7%BB%22%5D%0A%20%20J%20--%3E%20D%5B%22%E6%95%B0%E6%8D%AE%E5%8C%BA%3A%20%E5%AF%B9%E9%BD%90%E7%9A%84%E5%B0%8F%E7%AB%AF%E5%8E%9F%E5%A7%8B%E5%AD%97%E8%8A%82%22%5D%0A%20%20D%20--%3E%20T1%5B%22%E5%BC%A0%E9%87%8F%20A%20%E7%9A%84%E5%AD%97%E8%8A%82%E5%8C%BA%E9%97%B4%22%5D%0A%20%20D%20--%3E%20T2%5B%22%E5%BC%A0%E9%87%8F%20B%20%E7%9A%84%E5%AD%97%E8%8A%82%E5%8C%BA%E9%97%B4%22%5D%0A%20%20T1%20--%3E%20V1%5B%22mmap%20%E5%8F%AA%E8%AF%BB%E8%A7%86%E5%9B%BE%22%5D%0A%20%20T2%20--%3E%20V2%5B%22mmap%20%E5%8F%AA%E8%AF%BB%E8%A7%86%E5%9B%BE%22%5D%0A%20%20V1%20--%3E%20G%5B%22%E5%BC%82%E6%AD%A5%E6%8B%B7%E5%88%B0%20GPU%20%E6%88%96%E4%BE%9B%20CPU%20%E6%A0%B8%22%5D%0A%20%20V2%20--%3E%20G%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">数字实例：一个 7B 模型 FP16 数据区约 14 GB，JSON 头通常只有几十 KB——占比在百万分之几的量级。这就是「先读头再 mmap」划算的原因：用一次可忽略的解析，换来按张量名随机访问任意一块字节。</span></p><p><span class="marginnote">mmap 可以想象成「把文件页直接贴进进程地址空间」：程序拿到的是指向文件的指针，读到哪里操作系统才把对应的磁盘页调进内存。传统加载是先把整个文件抄进主机 RAM 再发给 GPU，等于多抄一整遍。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要用 <code>pickle.loads</code> 加载来路不明的检查点。不要把 safetensors 当万能容器塞 Python 对象。与 GGUF 的选择按运行时：vLLM/HF 一条，llama.cpp 一条。下一课程单元改谈 GPU 之外的运行时，从 ONNX Runtime 开始。<span class="marginnote">「零拷贝」不是完全不拷贝：磁盘到 GPU 之间的真传输省不掉，它省的是「在主机内存里多抄一遍」。对「主机内存 512 GB、模型权重 300 GB」的加载场景，这一遍就是能否启动而不 OOM 的区别。</span></p><p>出处：Hugging Face safetensors 规范与安全文档。无单独会议论文。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>safetensors 是可 mmap 的无执行张量容器；替代 pickle 检查点。</li><li>头 JSON、体原始数组；量化语义在模型代码。</li><li>与 config.json 配对；GGUF 是单文件本地生态。</li><li>零拷贝视图减主机峰值，设备仍要驻留副本。</li><li>加载与按层流式兼容。</li><li>下一课：ONNX Runtime。</li><li>出处：Hugging Face safetensors。</li></ul>',7))])}const F=p(d,[["render",B]]);export{g as __pageData,F as default};
